/// Get final JVM arguments for a specific Java version
/// Returns: (preset_args, custom_args, extra_args)
#[tauri::command]
pub fn get_java_args(java_version: u8, preset_id: String, custom_args: String, extra_args: String) -> (String, String, String) {
    // If custom selected, return custom + extra
    if preset_id == "custom" {
        return (String::new(), custom_args, extra_args);
    }

    // Get preset args for this version
    let preset_args = PRESET_ARGS
        .iter()
        .find(|(id, _)| id == &preset_id)
        .and_then(|(_, versions)| {
            versions
                .iter()
                .find(|(v, _)| v == &java_version.to_string())
                .map(|(_, args)| args.to_string())
        })
        .unwrap_or_default();

    // Only extra args are editable when using presets
    (preset_args, String::new(), extra_args)
}
